const readLocal=(key:string)=>{try{return localStorage.getItem(key);}catch{return null;}};
const writeLocal=(key:string,value:string)=>{try{localStorage.setItem(key,value);}catch{/* The flow still works without presentation history. */}};
const pendingKey=()=>`bookish-pending-clubs:${client.user?.id||'guest'}`;
