function readPending():string[]{const key=pendingKey();if(pendingByUser.has(key))return [...pendingByUser.get(key)!];let pending:string[]=[];try{const value:unknown=JSON.parse(readLocal(key)||'[]');if(Array.isArray(value)&&value.every(id=>typeof id==='string'))pending=value;}catch{/* Corrupt presentation history starts fresh. */}pendingByUser.set(key,[...pending]);return pending;}
